-- Aproveitamento didatico das questoes 20 a 29 do Exame CFC 2020.1.
-- Conteudo extraido do PDF "Prova 2020.1 - Resolvida - Parte 03.pdf", paginas 3 a 20.
do $$
declare
  v text;
begin
  -- Q20: conciliacao bancaria
  update public.study_materials
  set body_md=body_md || E'\n\n## Questao original — Consulplan/CFC 2020.1, questão 20: conciliação bancária\n\nO extrato bancário apresenta R$ 7.500, enquanto o razão contábil apresenta R$ 10.750. Foram identificados: despesas bancárias de R$ 300 não contabilizadas; débito de luz e telefone de R$ 700 não contabilizado; cheques emitidos e contabilizados de R$ 6.000 ainda não sacados; devolução de duplicata descontada de R$ 1.500 ainda não contabilizada; TED recebida de R$ 5.000 ainda não contabilizada; depósito em cheque de R$ 1.000 já contabilizado, mas ainda não creditado pelo banco.\n\n**Resposta: alternativa D — R$ 13.250.**\n\n### Resolução fácil\n\nComece pelo saldo do razão: R$ 10.750. Ajuste somente os fatos que o banco já registrou e a empresa ainda não lançou:\n- Despesas bancárias: −300.\n- Luz e telefone debitados pelo banco: −700.\n- Devolução de duplicata descontada: −1.500.\n- TED recebida e ainda não contabilizada: +5.000.\n\nCálculo: 10.750 − 300 − 700 − 1.500 + 5.000 = **R$ 13.250**.\n\nOs cheques emitidos ainda não sacados e o depósito ainda não creditado são diferenças temporárias entre banco e empresa: já estão registrados pela empresa e não exigem ajuste no razão neste momento.\n\n**Macete:** ajuste o razão pelos lançamentos que faltam na contabilidade. Cheque emitido não compensado e depósito em trânsito são diferenças de timing.\n\n### Treino autoral\n1. Uma tarifa bancária de R$ 120 aparece no extrato e ainda não foi lançada pela empresa. Ela reduz o saldo do razão na conciliação. **Certo ou errado?**\n2. Um cheque emitido e contabilizado, mas ainda não apresentado ao banco, deve ser novamente deduzido do razão. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** É despesa já debitada pelo banco e ainda ausente da escrituração. 2. **Errado.** A empresa já registrou a saída; falta apenas a compensação bancária.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Na questão 20 do CFC 2020.1, qual é o saldo correto do razão após a conciliação?","b":"R$ 13.250 — 10.750 − 300 − 700 − 1.500 + 5.000."},{"f":"Cheque emitido e ainda não compensado exige ajuste no razão?","b":"Não, se a empresa já contabilizou o cheque; é diferença temporária de compensação."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Na questão 20, a tarifa bancária de R$ 300 ainda não contabilizada reduz o saldo do razão.","a":true,"why":"O banco já debitou a conta; a empresa precisa reconhecer a despesa."},{"q":"Na questão 20, os cheques de R$ 6.000 emitidos e já contabilizados devem ser novamente deduzidos do razão.","a":false,"why":"A empresa já registrou a saída; falta apenas a compensação pelo banco."},{"q":"Na questão 20, o saldo correto do razão após os ajustes é R$ 13.250.","a":true,"why":"10.750 − 300 − 700 − 1.500 + 5.000 = 13.250."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 20, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, páginas 3–4.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-17-sistema-bancario-conciliacao-extrato-razao'
    and position('Questao original — Consulplan/CFC 2020.1, questão 20' in body_md)=0;

  -- Q21: depreciação
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 21: causas da depreciação\n\nA questão pergunta qual alternativa NÃO representa causa de depreciação de um bem do imobilizado: (A) desgaste pelo uso; (B) ação da natureza; (C) amortização do intangível; (D) obsolescência.\n\n**Resposta: alternativa C — amortização do intangível.**\n\n### Explicação fácil\n\nDepreciação é a apropriação sistemática do valor depreciável de um ativo tangível ao longo de sua vida útil. Ela pode refletir desgaste pelo uso, ação da natureza e obsolescência. Já a amortização é o termo usado, em regra, para ativos intangíveis com vida útil definida.\n\n**Macete:** tangível = depreciação; intangível com vida útil definida = amortização; recursos minerais/florestais = exaustão.\n\n### Treino autoral\n1. A perda de utilidade de uma máquina por obsolescência pode justificar depreciação. **Certo ou errado?**\n2. A amortização é o nome técnico usado para apropriar o custo de um veículo ao longo de sua vida útil. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** A obsolescência é uma das causas de redução da vida útil econômica. 2. **Errado.** Para veículo, bem tangível do imobilizado, utiliza-se depreciação.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Qual alternativa é a exceção na questão 21 do CFC 2020.1?","b":"Alternativa C — amortização do intangível não é causa de depreciação do imobilizado tangível."},{"f":"Qual a diferença básica entre depreciação e amortização?","b":"Depreciação é aplicada a ativos tangíveis; amortização, em regra, a intangíveis com vida útil definida."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Desgaste pelo uso, ação da natureza e obsolescência podem justificar depreciação.","a":true,"why":"São causas de consumo dos benefícios econômicos de ativos tangíveis."},{"q":"A amortização do intangível é uma causa de depreciação de um bem do imobilizado.","a":false,"why":"São conceitos aplicados a classes diferentes de ativos."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 21, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, página 5.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-14-imobilizado-depreciacao-provisoes-contingencias'
    and position('Questao original — Consulplan/CFC 2020.1, questão 21' in body_md)=0;

  -- Q22 folha
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 22: folha de pagamento e aumento do passivo\n\nDados da folha de abril/2017: remuneração bruta R$ 210.000; INSS retido dos empregados R$ 23.100; INSS patronal R$ 42.000; FGTS R$ 16.800. A pergunta é o aumento do Passivo Circulante.\n\n**Resposta: alternativa A — R$ 268.800.**\n\n### Resolução fácil\n\nO salário bruto de R$ 210.000 gera obrigação com os empregados e com os órgãos arrecadadores. O INSS retido de R$ 23.100 não é uma despesa adicional: é parte do salário bruto que a empresa retém para recolher. Por isso, não some o INSS retido novamente ao salário bruto. Some os encargos patronais:\n\n210.000 (salário bruto) + 42.000 (INSS patronal) + 16.800 (FGTS) = **R$ 268.800**.\n\nConferência por obrigações: salário líquido a pagar 186.900 + INSS retido 23.100 + INSS patronal 42.000 + FGTS 16.800 = R$ 268.800.\n\n**Pegadinha:** o INSS do empregado já está dentro da remuneração bruta. O INSS patronal e o FGTS são encargos da empresa.\n\n### Treino autoral\n1. Salários brutos de R$ 50.000, INSS patronal de R$ 10.000 e FGTS de R$ 4.000 geram aumento total do passivo de R$ 64.000. **Certo ou errado?**\n2. Se o INSS retido dos empregados for R$ 5.500, esse valor deve ser somado novamente aos salários brutos para calcular a obrigação total. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** 50.000 + 10.000 + 4.000 = 64.000. 2. **Errado.** A retenção já integra o salário bruto; apenas separa a quem a empresa deve pagar cada parcela.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Na questão 22 de folha do CFC 2020.1, qual é o aumento do passivo?","b":"R$ 268.800 — remuneração bruta de 210.000 + INSS patronal de 42.000 + FGTS de 16.800."},{"f":"O INSS retido do empregado deve ser somado novamente ao salário bruto?","b":"Não. Já está incluído na remuneração bruta; é apenas retido para recolhimento."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Na questão 22, o aumento do passivo é R$ 268.800.","a":true,"why":"210.000 + 42.000 + 16.800 = 268.800."},{"q":"O INSS retido dos empregados é encargo patronal adicional ao salário bruto.","a":false,"why":"É parcela da remuneração do empregado retida pela empresa para recolhimento."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 22 (folha), Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, página 6.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-18-folha-pagamento-encargos-inss-fgts'
    and position('Questao original — Consulplan/CFC 2020.1, questão 22: folha' in body_md)=0;

  -- Q23: ética profissional, incorporada na aula de fundamentos/classificação.
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 23: Código de Ética Profissional do Contador (NBC PG 01)\n\nA questão apresenta quatro afirmações sobre publicidade profissional, penalidades éticas, circunstâncias agravantes/atenuantes e liberdade profissional.\n\n**Resposta: alternativa B.** A transgressão de preceito da NBC PG 01 constitui infração ética e pode ser sancionada, conforme a gravidade, com advertência reservada, censura reservada ou censura pública.\n\n### Como eliminar as alternativas\n\n- **A — incorreta:** a norma não proíbe de forma absoluta a divulgação de títulos, especializações, serviços e trabalhos; a publicidade deve respeitar os critérios éticos e de caráter informativo, com autorização quando envolver clientes.\n- **B — correta:** enumera as três penalidades éticas indicadas no enunciado.\n- **C — incorreta:** os exemplos listados são circunstâncias agravantes, não atenuantes.\n- **D — incorreta:** o contador não deve renunciar à liberdade profissional nem aceitar restrições que prejudiquem a correção e a eficácia do trabalho.\n\n**Macete:** advertência reservada, censura reservada e censura pública. Na prova, cuidado para não trocar agravantes por atenuantes e para não confundir liberdade profissional com submissão a imposições indevidas.\n\n### Treino autoral\n1. A NBC PG 01 prevê advertência reservada, censura reservada e censura pública como penalidades éticas. **Certo ou errado?**\n2. O contador pode abrir mão de sua liberdade profissional quando o cliente exigir uma conduta que prejudique a correção do trabalho. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** São as três penalidades citadas no item correto. 2. **Errado.** A liberdade e a independência profissionais devem ser preservadas; o contador não deve aceitar imposições prejudiciais à qualidade do trabalho.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Quais penalidades éticas aparecem na questão 23 do CFC 2020.1?","b":"Advertência reservada, censura reservada e censura pública."},{"f":"Na questão 23, qual é a alternativa correta?","b":"Alternativa B: enumera as três penalidades éticas da NBC PG 01."},{"f":"O que a questão 23 ensina sobre liberdade profissional?","b":"O contador não deve renunciar à liberdade profissional nem aceitar imposições que prejudiquem a correção do trabalho."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"A NBC PG 01 prevê advertência reservada, censura reservada e censura pública.","a":true,"why":"São as três penalidades éticas indicadas no item correto da questão."},{"q":"As circunstâncias descritas na alternativa C da questão 23 são atenuantes.","a":false,"why":"O enunciado apresenta fatores agravantes, não atenuantes."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 23, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, página 9.'),
      updated_at=now()
  where slug='contabilidade-gabriel-rabelo-fundamentos-classificacao-2026'
    and position('Questao original — Consulplan/CFC 2020.1, questão 23' in body_md)=0;

  -- Q25: rateio departamental
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 25: rateio de custos comuns por departamento\n\nA indústria possui três departamentos: Serviço, Produção 1 e Produção 2. O departamento de Serviço ocupa 20 m², tem 40 empregados e 2 máquinas. No total, os departamentos ocupam 100 m², possuem 200 empregados e 10 máquinas. Os gastos comuns são: energia R$ 50.000 rateada por área; água, telefone e alimentação R$ 100.000 rateados por empregados; depreciação R$ 12.000 rateada por máquinas.\n\n**Resposta: alternativa B — R$ 32.400.**\n\n### Resolução por partes\n\n1. Energia: Serviço ocupa 20 de 100 m² = 20%. 20% × 50.000 = **R$ 10.000**.\n2. Água, telefone e alimentação: 40 de 200 empregados = 20%. 20% × 100.000 = **R$ 20.000**.\n3. Depreciação: 2 de 10 máquinas = 20%. 20% × 12.000 = **R$ 2.400**.\n\nTotal do Departamento de Serviço = 10.000 + 20.000 + 2.400 = **R$ 32.400**.\n\n**Macete:** para cada gasto, use a base indicada no enunciado. Não use a mesma base para todos os gastos.\n\n### Treino autoral\n1. Se um setor ocupa 30% da área e a energia total é R$ 20.000, sua parcela é R$ 6.000. **Certo ou errado?**\n2. Se um departamento tem 10 de 50 empregados, deve receber 10% de um gasto rateado por empregados. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** 30% × 20.000 = 6.000. 2. **Errado.** 10/50 = 20%, portanto recebe 20% do gasto.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Na questão 25 do CFC 2020.1, quanto de energia cabe ao Departamento de Serviço?","b":"R$ 10.000 — ocupa 20% da área total."},{"f":"Na questão 25, qual é o rateio de água, telefone e alimentação para Serviço?","b":"R$ 20.000 — 40 de 200 empregados representam 20%."},{"f":"Qual é o custo comum total alocado ao Departamento de Serviço na questão 25?","b":"R$ 32.400 — energia 10.000 + água/telefone/alimentação 20.000 + depreciação 2.400."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Na questão 25, o Departamento de Serviço recebe 20% do custo de energia porque ocupa 20% da área total.","a":true,"why":"20 m² ÷ 100 m² = 20%; 20% de 50.000 = 10.000."},{"q":"Na questão 25, o custo total rateado ao Departamento de Serviço é R$ 30.000.","a":false,"why":"O total é R$ 32.400: 10.000 + 20.000 + 2.400."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 25, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, páginas 11–13.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-08-custos-materia-prima-rateio-departamentalizacao'
    and position('Questao original — Consulplan/CFC 2020.1, questão 25' in body_md)=0;

  -- Q26: ROI e margem
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 26: ROI, margem sobre vendas e giro do ativo\n\nDados das divisões: X — vendas R$ 500.000, lucro líquido R$ 100.000 e giro do ativo 1,25; Y — vendas R$ 600.000, lucro R$ 100.000 e giro 1,20; Z — vendas R$ 550.000, lucro R$ 100.000 e giro 1,22.\n\n**Resposta: alternativa B — afirmativas I, III e IV.**\n\n### Como resolver\n\nROI = margem líquida × giro do ativo. A margem líquida é lucro líquido ÷ vendas.\n- X: margem 100.000/500.000 = 20%; ROI = 20% × 1,25 = **25%**.\n- Y: margem 100.000/600.000 = 16,67%; ROI = 16,67% × 1,20 = **20%**.\n- Z: margem 100.000/550.000 = 18,18%; ROI = 18,18% × 1,22 ≈ **22,18%**.\n\nI é verdadeira: X tem o maior ROI. II é falsa: Y e Z não têm a mesma margem; 16,67% é diferente de 18,18%. III é verdadeira conforme os giros informados: Z gira 1,22 vez e Y 1,20 vez, diferença de 0,02. IV é verdadeira: as margens são aproximadamente R$ 16,70 e R$ 18,20 por R$ 100 vendidos. V é falsa: os ROIs de Y e Z não são iguais.\n\n### Treino autoral\n1. Uma divisão tem margem líquida de 10% e giro do ativo de 2 vezes. Seu ROI é 20%. **Certo ou errado?**\n2. Duas divisões com o mesmo lucro líquido necessariamente possuem o mesmo ROI, mesmo que vendas e giro do ativo sejam diferentes. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** ROI = 10% × 2 = 20%. 2. **Errado.** O ROI depende também do investimento, da margem e do giro do ativo.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Qual é a fórmula do ROI pela margem e giro do ativo?","b":"ROI = margem líquida sobre vendas × giro do ativo."},{"f":"Na questão 26, qual divisão teve o maior ROI?","b":"Divisão X, com ROI de 25%."},{"f":"Quais afirmativas estão corretas na questão 26?","b":"I, III e IV — alternativa B."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Na questão 26, a divisão X tem ROI de 25%, superior ao de Y e Z.","a":true,"why":"X: margem de 20% × giro 1,25 = 25%; Y = 20%; Z ≈ 22,18%."},{"q":"Na questão 26, as divisões Y e Z têm a mesma margem líquida sobre vendas.","a":false,"why":"Y = 16,67%; Z = 18,18%."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 26, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, páginas 14–16.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-13-custeio-rkw-variavel-ponto-equilibrio'
    and position('Questao original — Consulplan/CFC 2020.1, questão 26' in body_md)=0;

  -- Q27: custeio por processo
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 27: estoque em elaboração pelo custeio por processo\n\nNo mês 1, os custos foram: matéria-prima R$ 2.500, mão de obra direta R$ 1.500 e custos indiretos de fabricação R$ 1.000. Foram iniciadas 1.100 unidades, acabadas 900 e ficaram 200 em elaboração com estágio de fabricação de 50%. A questão informa controle PEPS e pede o custo do estoque em elaboração.\n\n**Resposta: alternativa A — R$ 500.**\n\n### Resolução didática\n\nCustos totais do período = 2.500 + 1.500 + 1.000 = **R$ 5.000**. Produção equivalente indicada pelo enunciado: 900 unidades acabadas + 200 × 50% = 100 unidades equivalentes em elaboração, totalizando 1.000 unidades equivalentes.\n\nCusto por unidade equivalente = 5.000 ÷ 1.000 = **R$ 5**.\n\nEstoque em elaboração = 200 unidades × 50% × R$ 5 = **R$ 500**.\n\n**Atenção:** o cálculo segue a simplificação de equivalência física apresentada para o estágio de fabricação informado na questão.\n\n### Treino autoral\n1. Se 100 unidades estão 40% concluídas, equivalem a 40 unidades completas para fins de conversão, quando o percentual se aplica aos custos considerados. **Certo ou errado?**\n2. Com custo por unidade equivalente de R$ 8 e 50 unidades em elaboração a 50%, o custo do estoque em elaboração é R$ 400. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** 100 × 40% = 40 unidades equivalentes. 2. **Errado.** 50 × 50% × 8 = R$ 200.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Na questão 27, qual é o custo total de produção do mês?","b":"R$ 5.000 — matéria-prima 2.500 + MOD 1.500 + CIF 1.000."},{"f":"Na questão 27, quantas unidades equivalentes resultam de 200 unidades a 50%?","b":"100 unidades equivalentes."},{"f":"Qual é o custo do estoque em elaboração na questão 27?","b":"R$ 500 — 200 × 50% × custo equivalente de R$ 5."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Na questão 27, o custo total do período é R$ 5.000.","a":true,"why":"2.500 + 1.500 + 1.000 = 5.000."},{"q":"Duzentas unidades com 50% de acabamento representam 200 unidades equivalentes.","a":false,"why":"Representam 100 unidades equivalentes para o estágio considerado."},{"q":"Na questão 27, o estoque em elaboração é R$ 500.","a":true,"why":"Custo equivalente de R$ 5 × 100 unidades equivalentes = R$ 500."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 27, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, páginas 17–18.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-13-custeio-rkw-variavel-ponto-equilibrio'
    and position('Questao original — Consulplan/CFC 2020.1, questão 27' in body_md)=0;

  -- Q28: dividendos, reserva legal e ações em tesouraria
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 28: reserva legal e dividendo por ação\n\nCapital social integralizado: R$ 3.000.000; reserva legal existente: R$ 585.000; 3.000.000 ações emitidas, das quais 250.000 estão em tesouraria; lucro líquido: R$ 320.000; dividendo obrigatório: 25% do lucro líquido ajustado. O item afirma: I) reserva legal de R$ 16.000; II) dividendos de R$ 76.000; III) dividendo por ação de R$ 0,0275.\n\n**Resposta: alternativa A — todas as afirmativas estão incorretas.**\n\n### Resolução\n\n**Reserva legal:** 5% × 320.000 = R$ 16.000 seria o cálculo normal. Porém, a reserva legal não pode ultrapassar 20% do capital social: 20% × 3.000.000 = R$ 600.000. Já existem R$ 585.000; portanto, só cabem mais **R$ 15.000**. A afirmativa I está errada.\n\n**Lucro ajustado para o dividendo:** 320.000 − 15.000 = R$ 305.000. Dividendo obrigatório: 25% × 305.000 = **R$ 76.250**. A afirmativa II está errada, pois não é R$ 76.000.\n\n**Ações com direito ao dividendo:** 3.000.000 − 250.000 em tesouraria = 2.750.000 ações. Dividendo por ação = 76.250 ÷ 2.750.000 ≈ **R$ 0,027727**. A afirmativa III também está errada: não é R$ 0,0275.\n\n### Treino autoral\n1. Capital social de R$ 1.000.000 e reserva legal existente de R$ 195.000: o espaço até o limite de 20% é R$ 5.000. **Certo ou errado?**\n2. Ações em tesouraria devem ser incluídas no número de ações usado para dividir o dividendo por ação. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** Limite = 200.000; faltam 5.000. 2. **Errado.** Ações em tesouraria não recebem dividendos; devem ser excluídas das ações em circulação.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Na questão 28, qual é o limite de reserva legal?","b":"20% do capital social; compare o saldo existente com esse teto."},{"f":"Na questão 28, quanto ainda pode ser destinado à reserva legal?","b":"R$ 15.000 — limite de R$ 600.000 menos saldo existente de R$ 585.000."},{"f":"Na questão 28, qual é o dividendo obrigatório total?","b":"R$ 76.250 — 25% de R$ 305.000 de lucro ajustado."},{"f":"Ações em tesouraria entram no cálculo do dividendo por ação?","b":"Não. Excluem-se; na questão 28 são 2.750.000 ações em circulação."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Na questão 28, a reserva legal pode aumentar R$ 16.000, apesar de faltar apenas R$ 15.000 até o teto legal.","a":false,"why":"A constituição fica limitada ao espaço restante até 20% do capital: R$ 15.000."},{"q":"Na questão 28, o dividendo obrigatório é R$ 76.250.","a":true,"why":"25% × (320.000 − 15.000) = 76.250."},{"q":"As 250.000 ações em tesouraria devem ser excluídas do número de ações para calcular o dividendo por ação.","a":true,"why":"Ações em tesouraria não recebem dividendos."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 28, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, página 19.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-16-patrimonio-liquido-reservas-dividendos'
    and position('Questao original — Consulplan/CFC 2020.1, questão 28' in body_md)=0;

  -- Q29: média ponderada móvel
  update public.study_materials
  set body_md=body_md || E'\n\n## Questão original — Consulplan/CFC 2020.1, questão 29: média ponderada móvel e CMV\n\nEstoque inicial: 150 unidades por R$ 1.455. Em 10/10, compra de 200 unidades: nota de R$ 3.000, tributos recuperáveis R$ 540 e frete R$ 180. Em 16/10, compra de 500 unidades: nota de R$ 6.250, tributos recuperáveis R$ 750 e frete R$ 265. Em 27/10, venda de 420 unidades. A empresa utiliza média ponderada móvel.\n\n**Resposta: alternativa D — R$ 4.872.**\n\n### Resolução passo a passo\n\n1. Estoque inicial: custo de R$ 1.455.\n2. Primeira compra: custo de aquisição = 3.000 − 540 + 180 = **R$ 2.640**.\n3. Segunda compra: custo de aquisição = 6.250 − 750 + 265 = **R$ 5.765**.\n4. Custo total disponível = 1.455 + 2.640 + 5.765 = **R$ 9.860**.\n5. Quantidade disponível = 150 + 200 + 500 = **850 unidades**.\n6. Custo médio móvel antes da venda = 9.860 ÷ 850 = **R$ 11,60 por unidade**.\n7. CMV = 420 × 11,60 = **R$ 4.872**.\n\nTributos recuperáveis são excluídos do custo do estoque; frete diretamente atribuível à compra integra o custo.\n\n**Macete:** média móvel = custo total disponível ÷ quantidade total disponível; depois multiplique pelo número de unidades vendidas.\n\n### Treino autoral\n1. Estoque de 100 unidades a R$ 10 e compra de 100 unidades a R$ 14 geram média ponderada de R$ 12 por unidade. **Certo ou errado?**\n2. Com custo médio de R$ 12 e venda de 30 unidades, o CMV é R$ 360. **Certo ou errado?**\n\n**Gabarito comentado:** 1. **Certo.** (1.000 + 1.400) ÷ 200 = 12. 2. **Certo.** 30 × 12 = 360.\n',
      flashcards=coalesce(flashcards,'[]'::jsonb) || '[{"f":"Na questão 29, como tratar tributos recuperáveis no custo de aquisição?","b":"Deduzir da nota fiscal; não integram o custo do estoque."},{"f":"Na questão 29, como tratar o frete de compra?","b":"Somar ao custo de aquisição, pois é diretamente atribuível à compra."},{"f":"Qual é a média ponderada móvel antes da venda na questão 29?","b":"R$ 11,60 por unidade — R$ 9.860 ÷ 850 unidades."},{"f":"Qual é o CMV da questão 29?","b":"R$ 4.872 — 420 unidades × R$ 11,60."}]'::jsonb,
      quiz=coalesce(quiz,'[]'::jsonb) || '[{"q":"Na questão 29, os tributos recuperáveis são deduzidos da nota fiscal para calcular o custo do estoque.","a":true,"why":"Tributos recuperáveis não integram o custo de aquisição."},{"q":"Na questão 29, o frete diretamente atribuível à compra deve ser excluído do custo do estoque.","a":false,"why":"O frete de aquisição integra o custo do estoque."},{"q":"Na questão 29, o CMV é R$ 4.872.","a":true,"why":"Custo médio 11,60 × 420 unidades vendidas = 4.872."}]'::jsonb,
      source_note=concat_ws('; ',nullif(source_note,''),'Questão 29, Consulplan/CFC 2020.1, PDF Prova 2020.1 - Resolvida - Parte 03, página 20.'),
      updated_at=now()
  where slug='pcac-2026-contabilidade-11-estoques-mensuracao-avp-inventarios'
    and position('Questao original — Consulplan/CFC 2020.1, questão 29' in body_md)=0;
end $$;
